import type {ApiProps, StackContext} from 'sst/constructs';
import {Api, use} from 'sst/constructs';
import {AppConfig} from './AppConfig';

type Routes = Record<
  string,
  {
    function: {
      handler: string;
      timeout?: number;
      memorySize?: number;
      functionName?: string;
    };
  }
>;
const getBffName = (path: string) => path.split(`/`).pop();
const getBffMethod = (path: string) => path.split(` `)[0];
const enrichRoutes = (
  routes: Routes,
  target: string,
  stage: string,
): ApiProps['routes'] => {
  if (routes) {
    return Object.entries(routes).reduce<ApiProps['routes']>(
      (
        acc,
        [
          path,
          {
            [`function`]: {handler, timeout, memorySize},
          },
        ],
      ) => {
        if (acc)
          acc[path] = {
            function: {
              handler,
              ...(timeout && {timeout}),
              ...(memorySize && {memorySize}),
              functionName: `BFF-${target.toUpperCase()}-${getBffMethod(
                path,
              )}-${getBffName(path)}-${stage}`,
              description: `${getBffName(path)} ${target} => ${
                path.split(` `)[1]
              }`,
            },
          };
        return acc;
      },
      {},
    );
  }
  return routes;
};

export function BffApi({stack}: StackContext) {
  const {hostedZone, target, featureAppName} = use(AppConfig);
  const baseUrl = `/__app__/${featureAppName}/${target}`;
  const routes: Routes = {
    [`GET ${baseUrl}/bff/app-model`]: {
      function: {
        handler: `src/bff/app-model/index.handler`,
        functionName: `${featureAppName}-${target}-app-model`,
      },
    },
    [`GET ${baseUrl}/bff/product-search-model`]: {
      function: {
        handler: `src/bff/product-search-model/index.handler`,
        functionName: `${featureAppName}-${target}-product-search-model`,
      },
    },
  };

  const api = new Api(stack, `api`, {
    customDomain: {
      hostedZone,
      domainName: [`stage`, `dev`, `prod`].includes(stack.stage)
        ? `bff.${hostedZone}`
        : `bff.${stack.stage}.${hostedZone}`,
    },
    routes: enrichRoutes(routes, target, stack.stage),
  });

  stack.addOutputs({
    apiUrl: api.customDomainUrl ?? api.url,
  });

  return api;
}

