import path from 'path';
import {BuildTimestampPlugin} from '@smart/server-utils';
import CopyWebpackPlugin from 'copy-webpack-plugin';
import HtmlInlineCssWebpackPlugin from 'html-inline-css-webpack-plugin';
import HtmlWebpackPlugin from 'html-webpack-plugin';
import MiniCssExtractPlugin from 'mini-css-extract-plugin';
import type {Configuration} from 'webpack';
import webpack from 'webpack';
import type {Configuration as WebpackDevServerConfiguration} from 'webpack-dev-server';
import merge from 'webpack-merge';
import {buildPath, getCommonConfig} from './webpack.config.common';

interface WebAppOptions {
  readonly mode: Configuration['mode'];
  readonly stage: string;
  readonly target: string;
  readonly baseUrl: string;
  readonly privateBaseUrl: string;
  readonly featureAppName: string;
  readonly hostedZone: string;
}

export const getWebAppConfig = (
  options: WebAppOptions,
): Configuration & WebpackDevServerConfiguration => {
  const config: Configuration & WebpackDevServerConfiguration = {
    mode: options.mode,
    entry: [buildPath(`src`, `feature-app`, `index.tsx`)],
    output: {
      filename: `index.js`,
      path: buildPath(`build`, `assets`),
      publicPath: `auto`,
    },
    devServer: {
      port: process.env.PORT ?? 3000,
      proxy: [
        {
          path: () => false,
          context: (pathname) => {
            if (
              pathname.startsWith(`/__app__/`) ||
              pathname.startsWith(`/__app-private__/`)
            ) {
              const [_, _appPath, featureAppName] = pathname.split(`/`);
              return featureAppName !== options.featureAppName;
            }
            return false;
          },
          target: `https://${options.stage}.${options.hostedZone}`,
          changeOrigin: true,
          router: ({path: p}) => {
            const [_, _appPath, featureAppName, env] = p.split(`/`);
            return `https://${env}.${featureAppName}.feature-app.srv.smart.com`;
          },
          logLevel: `debug`,
          secure: false,
        },
        {
          context: (pathname) =>
            pathname.startsWith(`${options.baseUrl}/bff`) ||
            pathname.startsWith(`${options.privateBaseUrl}/bff`),
          target: `https://bff.${options.stage}.${options.hostedZone}`,
          changeOrigin: true,
          logLevel: `debug`,
          secure: false,
        },
      ],
      onListening: () => {
        console.log(`Listening on port: ${process.env.PORT ?? 3000}`);
      },
    },

    plugins: [
      new HtmlWebpackPlugin({
        template: buildPath(`src`, `feature-app`, `index.html`),
        filename:
          options.mode === `development` ? `index.html` : `../index.html`,
        cache: false,
        templateParameters: {baseUrl: options.baseUrl},
      }),
      new webpack.SourceMapDevToolPlugin({
        filename: `[file].map`,
        publicPath: `${options.baseUrl}/assets/`,
        namespace: `${options.featureAppName}/${options.target}`,
      }),
      new MiniCssExtractPlugin({filename: `index.css`}),
      new HtmlInlineCssWebpackPlugin(),
      new CopyWebpackPlugin({
        patterns: [
          `static`,
          path.join(
            path.dirname(require.resolve(`@smart/web-components/package.json`)),
            `dist/assets`,
          ),
        ],
      }),
      new webpack.container.ModuleFederationPlugin({
        shared: {
          'react': {singleton: true, eager: true},
          'react-dom': {
            singleton: true,
            eager: true,
            requiredVersion: false,
          },
          '@feature-hub/react': {singleton: true, eager: true},
        },
      }),
      new BuildTimestampPlugin({target: options.target}),
    ],
    resolve: {
      fallback: {
        child_process: false,
      },
    },
  };

  return merge(getCommonConfig(options), config);
};

